// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.leo;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;

/**
 * The rollout profile is the operator-facing kill switch for learned cardinality corrections. Anything that is not a
 * known profile name must fail closed: a misspelling or a common negative spelling must never silently enable
 * corrections through the unconfigured default.
 */
class LeoRolloutProfileFailClosedTest {

	@Test
	void unrecognizedProfileNameMustFailClosed() {
		for (String typo : List.of("disabled", "false", "none", "of", "0")) {
			LeoRolloutProfile parsed = LeoRolloutProfile.parse(typo, LeoRolloutProfile.SAFE_CARDINALITY_CORRECTION);
			assertFalse(parsed.cardinalityCorrectionEnabled(),
					"profile value '" + typo + "' silently enables cardinality correction (" + parsed + ")");
		}
	}

	@Test
	void explicitNegativeAliasesResolveToOff() {
		for (String alias : List.of("off", "OFF", " Off ", "disabled", "DISABLED", "false", "none", "0")) {
			assertEquals(LeoRolloutProfile.OFF,
					LeoRolloutProfile.parse(alias, LeoRolloutProfile.SAFE_CARDINALITY_CORRECTION),
					"negative alias '" + alias + "' must disable LEO");
		}
	}

	@Test
	void typosOfKnownProfilesResolveToOffNotToTheFallback() {
		for (String typo : List.of("experimental_ful", "safe-cardinality-corection", "observe", "shadow",
				"SAFE_PLAN_LIFECYCLE_", "true", "on", "1")) {
			LeoRolloutProfile parsed = LeoRolloutProfile.parse(typo, LeoRolloutProfile.EXPERIMENTAL_FULL);
			assertEquals(LeoRolloutProfile.OFF, parsed, "unknown value '" + typo + "' must not use the fallback");
		}
	}

	@Test
	void knownProfilesResolveCaseAndSeparatorInsensitively() {
		assertEquals(LeoRolloutProfile.SAFE_CARDINALITY_CORRECTION,
				LeoRolloutProfile.parse("SAFE-CARDINALITY-CORRECTION", LeoRolloutProfile.OFF));
		assertEquals(LeoRolloutProfile.SAFE_CARDINALITY_CORRECTION,
				LeoRolloutProfile.parse("safe_cardinality_correction", LeoRolloutProfile.OFF));
		assertEquals(LeoRolloutProfile.SAFE_PLAN_LIFECYCLE,
				LeoRolloutProfile.parse(" safe-plan-lifecycle ", LeoRolloutProfile.OFF));
		assertEquals(LeoRolloutProfile.OBSERVE_ONLY, LeoRolloutProfile.parse("Observe-Only", LeoRolloutProfile.OFF));
		for (LeoRolloutProfile profile : LeoRolloutProfile.values()) {
			assertEquals(profile, LeoRolloutProfile.parse(profile.name(), LeoRolloutProfile.OFF));
			assertEquals(profile, LeoRolloutProfile.parse(profile.externalName(), LeoRolloutProfile.OFF));
		}
	}

	@Test
	void blankValuesKeepTheFallback() {
		assertEquals(LeoRolloutProfile.SAFE_CARDINALITY_CORRECTION,
				LeoRolloutProfile.parse(null, LeoRolloutProfile.SAFE_CARDINALITY_CORRECTION));
		assertEquals(LeoRolloutProfile.SAFE_CARDINALITY_CORRECTION,
				LeoRolloutProfile.parse("   ", LeoRolloutProfile.SAFE_CARDINALITY_CORRECTION));
		assertEquals(LeoRolloutProfile.OFF, LeoRolloutProfile.parse("", null));
	}

	@Test
	void unknownSystemPropertyValueDisablesLeo() {
		String rollout = System.getProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY);
		String current = System.getProperty(LeoRolloutProfile.PROPERTY);
		String legacy = System.getProperty(LeoRolloutProfile.LEGACY_PROFILE_PROPERTY);
		try {
			System.clearProperty(LeoRolloutProfile.PROPERTY);
			System.clearProperty(LeoRolloutProfile.LEGACY_PROFILE_PROPERTY);
			for (String value : List.of("disabled", "false", "off", "none", "0", "typo")) {
				System.setProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, value);
				LeoRolloutProfile profile = LeoRolloutProfile.fromSystemProperties();
				assertEquals(LeoRolloutProfile.OFF, profile, "system property '" + value + "' must disable LEO");
				assertFalse(profile.observationEnabled());
				assertFalse(profile.cardinalityCorrectionEnabled());
			}
		} finally {
			restore(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, rollout);
			restore(LeoRolloutProfile.PROPERTY, current);
			restore(LeoRolloutProfile.LEGACY_PROFILE_PROPERTY, legacy);
		}
	}

	@Test
	void rolloutLadderMustBeMonotone() {
		LeoRolloutProfile[] ladder = LeoRolloutProfile.values();
		List<String> violations = new ArrayList<>();
		for (int i = 1; i < ladder.length; i++) {
			LeoRolloutProfile lower = ladder[i - 1];
			LeoRolloutProfile higher = ladder[i];
			boolean[] lowerFlags = flags(lower);
			boolean[] higherFlags = flags(higher);
			boolean gainedFeature = false;
			for (int flag = 0; flag < lowerFlags.length; flag++) {
				if (lowerFlags[flag] && !higherFlags[flag]) {
					violations.add(higher + " drops " + FLAG_NAMES[flag] + " enabled by lower rung " + lower);
				}
				gainedFeature |= !lowerFlags[flag] && higherFlags[flag];
			}
			if (!gainedFeature && higher != LeoRolloutProfile.EXPERIMENTAL_FULL) {
				violations.add(lower + " == " + higher + " (" + signature(higher) + ")");
			}
		}
		for (boolean flag : flags(LeoRolloutProfile.EXPERIMENTAL_FULL)) {
			if (!flag) {
				violations.add("EXPERIMENTAL_FULL must enable every feature: "
						+ signature(LeoRolloutProfile.EXPERIMENTAL_FULL));
			}
		}
		assertTrue(violations.isEmpty(), "rollout ladder violations: " + violations);
	}

	@Test
	void safeRungsBeyondCorrectionKeepThePlanLifecycleSafetyNet() {
		assertTrue(LeoRolloutProfile.SAFE_RULE_STEERING.planLifecycleEnforced());
		assertTrue(LeoRolloutProfile.SAFE_PLAN_RERANKING.planLifecycleEnforced());
		assertTrue(LeoRolloutProfile.SHADOW_EXPLAIN.explainEnabled());
		assertFalse(LeoRolloutProfile.OBSERVE_ONLY.explainEnabled());
		assertFalse(LeoRolloutProfile.SAFE_PLAN_LIFECYCLE.ruleSteeringEnabled());
		assertTrue(LeoRolloutProfile.SAFE_RULE_STEERING.ruleSteeringEnabled());
	}

	private static final String[] FLAG_NAMES = { "observation", "explain", "cardinality correction",
			"rule steering", "plan reranking", "lifecycle enforcement" };

	private static boolean[] flags(LeoRolloutProfile profile) {
		return new boolean[] { profile.observationEnabled(), profile.explainEnabled(),
				profile.cardinalityCorrectionEnabled(), profile.ruleSteeringEnabled(), profile.planRerankingEnabled(),
				profile.planLifecycleEnforced() };
	}

	private static String signature(LeoRolloutProfile profile) {
		StringBuilder signature = new StringBuilder();
		for (boolean flag : flags(profile)) {
			signature.append(flag ? '1' : '0');
		}
		return signature.toString();
	}

	private static void restore(String property, String value) {
		if (value == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, value);
		}
	}
}
